import numpy as np
lines = open('complex_opt.xyz').read().splitlines()
n=int(lines[0]); els=[]; xyz=[]
for l in lines[2:2+n]:
    p=l.split(); els.append(p[0]); xyz.append([float(v) for v in p[1:4]])
xyz=np.array(xyz)
pairs=[]
for i in range(89):
    for j in range(89,103):
        d=np.linalg.norm(xyz[i]-xyz[j])
        if d<3.0: pairs.append((round(d,2), i, els[i], j, els[j]))
for p in sorted(pairs)[:10]: print(p)
EOF
